import json, re, csv, shutil, subprocess, os
from pathlib import Path

ROOT = Path('/mnt/data/ped_work/klinik_v395_work')
REPORT = ROOT/'reports/pediatrics_glossary_expansion'
REPORT.mkdir(parents=True, exist_ok=True)

payload = json.load(open(REPORT/'pediatrics-text-fields-v404.json', encoding='utf-8'))
texts = payload['texts']
source_inventory = payload['sourceInventory']
glossary_payload = json.load(open(REPORT/'pediatrics-active-glossary-terms-v404.json', encoding='utf-8'))

def norm(s):
    s = str(s or '').strip()
    s = s.replace('İ','i').replace('I','ı').lower().replace('ı','i')
    for a,b in [('ğ','g'),('ü','u'),('ş','s'),('ö','o'),('ç','c')]: s = s.replace(a,b)
    s = re.sub(r'[^\w+/.-]+',' ',s,flags=re.UNICODE)
    return re.sub(r'\s+',' ',s).strip()

def slug(s):
    x = norm(s)
    x = re.sub(r'[^a-z0-9]+','-',x).strip('-')
    return x[:90] or 'term'

active_norms = set()
for g in glossary_payload:
    if g.get('term'): active_norms.add(norm(g['term']))
    for a in g.get('aliases') or []:
        if a: active_norms.add(norm(a))

items = []
for t in texts:
    nt = norm(t.get('text',''))
    if nt:
        items.append({**t, 'normText': nt})

def count_occ(term, aliases=None):
    keys = [norm(term)] + [norm(a) for a in (aliases or [])]
    keys = [k for k in keys if k]
    c = 0
    for it in items:
        tx = it['normText']
        if any(k and k in tx for k in keys): c += 1
    return c

def examples(term, aliases=None, maxn=2):
    keys = [norm(term)] + [norm(a) for a in (aliases or [])]
    keys = [k for k in keys if k]
    out=[]
    seen=set()
    for it in items:
        tx = it['normText']
        if any(k and k in tx for k in keys):
            key=(it['path'], it['text'][:120])
            if key in seen: continue
            seen.add(key)
            out.append({'sourceFilePath': it['path'], 'text': it['text'][:440]})
            if len(out)>=maxn: break
    return out


def e(term, sub, short, detail, pearl, diff, nested=None, aliases=None, priority='P1', leak='low', ambiguity='low', phrase=True):
    aliases = aliases or []
    # keep canonical in aliases for matching variants, later deduped
    return dict(term=term, aliases=aliases, subcategory=sub, short=short, detail=detail, pearl=pearl, diff=diff, nested=nested or [], priority=priority, answerLeakRisk=leak, ambiguityRisk=ambiguity, phraseOnly=phrase)

