for e0 in entries:
    md.append(f"- **{e0['term']}** ({e0['priority']}, {e0['subcategory']}): {e0['shortDefinition']}")
(REPORT/'pediatrics-glossary-additions-v404-summary.md').write_text('\n'.join(md), encoding='utf-8')

